def get_neighbors(x, y):
    """Get all 6 neighbor coordinates for a hex tile in Civ6 offset coordinates"""
    if y % 2 == 0:  # Even row
        neighbors = [
            (x+1, y+1),  # NE
            (x+1, y),    # E
            (x+1, y-1),  # SE
            (x, y-1),    # SW
            (x-1, y),    # W
            (x, y+1),    # NW
        ]
    else:  # Odd row
        neighbors = [
            (x, y+1),    # NE
            (x+1, y),    # E
            (x, y-1),    # SE
            (x-1, y-1),  # SW
            (x-1, y),    # W
            (x-1, y+1),  # NW
        ]
    return [(nx, ny) for nx, ny in neighbors if 0 <= nx < WIDTH and 0 <= ny < HEIGHT]

# Get all plots
plots = {}
for row in conn.execute("SELECT ID, TerrainType, IsImpassable FROM Plots"):
    x, y = id_to_xy(row[0])
    plots[(x, y)] = {'terrain': row[1], 'impassable': row[2]}

