rivers = {}
for row in conn.execute("SELECT ID, IsNEOfRiver, IsWOfRiver, IsNWOfRiver FROM PlotRivers"):
    x, y = id_to_xy(row[0])
    rivers[(x, y)] = {'NE': row[1], 'W': row[2], 'NW': row[3]}

def count_river_edges(x, y):
    """Count river edges for a tile"""
    count = 0
    r = rivers.get((x, y), {})
    if r.get('NE', 0): count += 1
    if r.get('W', 0): count += 1
    if r.get('NW', 0): count += 1
    # Also check the other tiles for edges pointing to this tile
    for nx, ny in get_neighbors(x, y):
        nr = rivers.get((nx, ny), {})
        # Determine which edge from neighbor points to us
        if y % 2 == 0:
            if (nx, ny) == (x, y-1):  # SW neighbor - their NE edge
                if nr.get('NE', 0): count += 1
            elif (nx, ny) == (x+1, y-1):  # SE neighbor - their NW edge
                if nr.get('NW', 0): count += 1
            elif (nx, ny) == (x+1, y):  # E neighbor - their W edge
                if nr.get('W', 0): count += 1
        else:
            if (nx, ny) == (x-1, y-1):  # SW neighbor - their NE edge
                if nr.get('NE', 0): count += 1
            elif (nx, ny) == (x, y-1):  # SE neighbor - their NW edge  
                if nr.get('NW', 0): count += 1
            elif (nx, ny) == (x+1, y):  # E neighbor - their W edge
                if nr.get('W', 0): count += 1
    return count

# Check if a tile is a mountain
def is_mountain(x, y):
    if (x, y) not in plots:
        return False
    return 'MOUNTAIN' in plots[(x, y)]['terrain']

