# Find valid land tiles for district placement
valid_tiles = set()
for (x, y), data in plots.items():
    if data['terrain'] in ['TERRAIN_GRASS', 'TERRAIN_PLAINS'] and not data['impassable']:
        valid_tiles.add((x, y))

print(f"Valid land tiles: {len(valid_tiles)}")

# City center must be on valid land with at least 3 workable tiles within range 3
# For simplicity, we'll consider tiles within Manhattan distance 3 (hex distance)
def tiles_in_range(cx, cy, max_range=3):
    """Get all tiles within hex range of a center"""
    result = set()
    for (x, y) in plots.keys():
        # Use simple hex distance calculation
        # BFS to find tiles within range
        dist = hex_distance(cx, cy, x, y)
        if dist <= max_range:
            result.add((x, y))
    return result

def hex_distance(x1, y1, x2, y2):
    """Calculate hex distance using cube coordinates"""
    # Convert offset to cube coordinates
    def offset_to_cube(x, y):
        cx = x - (y - (y & 1)) // 2
        cz = y
        cy = -cx - cz
        return (cx, cy, cz)

    c1 = offset_to_cube(x1, y1)
    c2 = offset_to_cube(x2, y2)
