            bonus += 2
    return bonus

def calc_industrial_zone_adjacency(x, y, placements):
    """Industrial Zone: +1 per 2 adjacent districts, +1 per adjacent mine/quarry, +2 per adjacent aqueduct/dam/canal"""
    bonus = 0
    district_count = 0
    for nx, ny in get_neighbors(x, y):
        if (nx, ny) in placements:
