        neighbors = [(x+1, y+1), (x+1, y), (x+1, y-1), (x, y-1), (x-1, y), (x, y+1)]
    else:
        neighbors = [(x, y+1), (x+1, y), (x, y-1), (x-1, y-1), (x-1, y), (x-1, y+1)]
    return [(nx, ny) for nx, ny in neighbors if 0 <= nx < WIDTH and 0 <= ny < HEIGHT]

def hex_distance(x1, y1, x2, y2):
    def offset_to_cube(x, y):
        cx = x - (y - (y & 1)) // 2
        cz = y
        cy = -cx - cz
        return (cx, cy, cz)
    c1 = offset_to_cube(x1, y1)
    c2 = offset_to_cube(x2, y2)
    return max(abs(c1[0] - c2[0]), abs(c1[1] - c2[1]), abs(c1[2] - c2[2]))

